def trf011_check_pp_unsafe_attribute_access(
    tree: ast.Module, file_path: Path, source_lines: list[str], violations: list[Violation], rule_id: str
) -> list[Violation]:
    # The PP plan mapping must be populated for this rule to have anything to check against.
    if not _PP_PLAN_MODULES_BY_MODEL_DIR:
        return violations

    model_dir = _model_dir_name(file_path)
    if model_dir is None:
        return violations

    pp_modules = _PP_PLAN_MODULES_BY_MODEL_DIR.get(model_dir)
    if not pp_modules:
        return violations

    class_to_bases = _collect_class_bases(tree)
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        if not _inherits_pretrained_model(node.name, class_to_bases):
            continue

        forward_method = _class_methods(node).get("forward")
        if forward_method is None:
            continue

        _collect_pp_attribute_violations(
            forward_method, pp_modules, file_path, source_lines, violations, rule_id
        )

    return violations


